import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Paper,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  IconButton,
  TextField,
  InputAdornment,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Grid,
  CircularProgress
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import Layout from '../components/Layout';
import { moviesAPI } from '../services/api';

const parseDuration = (isoDuration) => {
  if (!isoDuration || typeof isoDuration !== 'string') return 0;
  const hourMatch = isoDuration.match(/(\d+)H/);
  const minuteMatch = isoDuration.match(/(\d+)M/);
  const hours = hourMatch ? parseInt(hourMatch[1], 10) : 0;
  const minutes = minuteMatch ? parseInt(minuteMatch[1], 10) : 0;
  return hours * 60 + minutes;
};

const toISODuration = (minutes) => {
  const mins = parseInt(minutes, 10);
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `PT${h > 0 ? `${h}H` : ''}${m > 0 ? `${m}M` : ''}` || 'PT0M';
};

const MoviesManagement = () => {
  const [loading, setLoading] = useState(true);
  const [movies, setMovies] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [openDialog, setOpenDialog] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [saving, setSaving] = useState(false);
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [movieForm, setMovieForm] = useState({ title: '', duration: '', PosterURL: '', description: '' });

  useEffect(() => {
    const fetchMovies = async () => {
      try {
        setLoading(true);
        const data = await moviesAPI.getAllMovies();
        setMovies(data.map(m => ({
          ...m,
          duration: typeof m.duration === 'string' ? parseDuration(m.duration) : m.duration
        })));
      } catch (error) {
        console.error('Fetch movies error:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchMovies();
  }, []);

  const handleSave = async () => {
    if (!movieForm.title || !movieForm.duration) return;
    setSaving(true);
    const payload = {
      ...movieForm,
      duration: toISODuration(movieForm.duration)
    };
    try {
      if (editMode && selectedMovie) {
        await moviesAPI.updateMovie(selectedMovie.id, payload);
      } else {
        await moviesAPI.createMovie(payload);
      }
      const data = await moviesAPI.getAllMovies();
      setMovies(data.map(m => ({ ...m, duration: parseDuration(m.duration) })));
      setOpenDialog(false);
      setMovieForm({ title: '', duration: '', PosterURL: '', description: '' });
    } catch (error) {
      console.error('Save movie error:', error);
    } finally {
      setSaving(false);
    }
  };

  const handleEdit = (movie) => {
    setSelectedMovie(movie);
    setMovieForm({
      title: movie.title,
      duration: movie.duration,
      PosterURL: movie.PosterURL || '',
      description: movie.description || ''
    });
    setEditMode(true);
    setOpenDialog(true);
  };

  const handleDelete = async (movieId) => {
    try {
      await moviesAPI.deleteMovie(movieId);
      setMovies(movies.filter(m => m.id !== movieId));
    } catch (error) {
      console.error('Delete error:', error);
    }
  };

  const filteredMovies = movies.filter(m => m.title.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <Layout>
      <Box sx={{ flexGrow: 1 }}>
        <Typography variant="h4" gutterBottom>Quản lý phim</Typography>

        <Paper sx={{ p: 2, mb: 3 }}>
          <TextField
            fullWidth
            variant="outlined"
            placeholder="Tìm kiếm phim..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              )
            }}
          />
        </Paper>

        <Button variant="contained" startIcon={<AddIcon />} onClick={() => { setOpenDialog(true); setEditMode(false); setMovieForm({ title: '', duration: '', PosterURL: '', description: '' }); }}>Thêm phim</Button>

        <TableContainer component={Paper} sx={{ mt: 2 }}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Tên phim</TableCell>
                <TableCell>Thời lượng</TableCell>
                <TableCell>Mô tả</TableCell>
                <TableCell align="right">Hành động</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow><TableCell colSpan={4}><CircularProgress /></TableCell></TableRow>
              ) : filteredMovies.length ? (
                filteredMovies.map((movie) => (
                  <TableRow key={movie.id}>
                    <TableCell>{movie.title}</TableCell>
                    <TableCell>{movie.duration} phút</TableCell>
                    <TableCell>{movie.description}</TableCell>
                    <TableCell align="right">
                      <IconButton onClick={() => handleEdit(movie)}><EditIcon /></IconButton>
                      <IconButton color="error" onClick={() => handleDelete(movie.id)}><DeleteIcon /></IconButton>
                    </TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow><TableCell colSpan={4}>Không có phim nào</TableCell></TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <Dialog open={openDialog} onClose={() => setOpenDialog(false)}>
          <DialogTitle>{editMode ? 'Chỉnh sửa phim' : 'Thêm phim mới'}</DialogTitle>
          <DialogContent>
            <TextField fullWidth margin="normal" label="Tên phim" value={movieForm.title} onChange={(e) => setMovieForm({ ...movieForm, title: e.target.value })} />
            <TextField fullWidth margin="normal" label="Thời lượng (phút)" type="number" value={movieForm.duration} onChange={(e) => setMovieForm({ ...movieForm, duration: e.target.value })} />
            <TextField fullWidth margin="normal" label="URL Poster" value={movieForm.PosterURL} onChange={(e) => setMovieForm({ ...movieForm, PosterURL: e.target.value })} />
            <TextField fullWidth margin="normal" label="Mô tả" multiline rows={3} value={movieForm.description} onChange={(e) => setMovieForm({ ...movieForm, description: e.target.value })} />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setOpenDialog(false)}>Hủy</Button>
            <Button onClick={handleSave} variant="contained" disabled={saving}>{saving ? 'Đang lưu...' : 'Lưu'}</Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Layout>
  );
};

export default MoviesManagement;
